Deduplication should use the stable Sentry **issue ID**, stored in the generated card’s frontmatter.

On every run, the script:

- Reads existing Markdown files.
- Collects every `sentryIssueId`.
- Retrieves unresolved Sentry issues.
- Skips IDs already present.
- Creates files only for missing IDs.

MD² preserves unknown frontmatter fields when serializing cards, so `sentryIssueId` is safe for this purpose; see [`markdown_parsing_service.ts`](C:/Users/janbo/Documents/dev/md2/app/src/services/data/markdown_parsing_service.ts:508).

## Example importer

Create `scripts/import_sentry_issues.mjs`:

```javascript
import { randomUUID } from 'node:crypto';
import { readdir, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';

const WORKING_FOLDER = 'design/feature_descriptions';
const SENTRY_ISSUE_ID_PATTERN = /^sentryIssueId:\s*["']?(\d+)["']?\s*$/mu;
const BUG_FILE_PATTERN = /^B[-_](\d+)[-_].+\.md$/u;

function requireEnvironmentVariable(name) {
    const value = process.env[name]?.trim();
    if (!value) throw new Error(`Missing environment variable: ${name}`);

    return value;
}

function slugify(value) {
    const slug = value
        .toLowerCase()
        .replace(/[^a-z0-9]+/gu, '_')
        .replace(/^_+|_+$/gu, '');

    return slug || 'sentry_error';
}

function quoteYaml(value) {
    return JSON.stringify(String(value));
}

function findNextPage(response) {
    const linkHeader = response.headers.get('link');
    if (!linkHeader) return null;

    const nextLink = linkHeader
        .split(',')
        .find((link) => link.includes('rel="next"') && link.includes('results="true"'));

    return nextLink?.match(/<([^>]+)>/u)?.[1] ?? null;
}

async function sentryRequest(url, token) {
    const response = await fetch(url, {
        headers: {
            Authorization: `Bearer ${token}`,
        },
    });

    if (!response.ok) {
        const responseBody = await response.text();
        throw new Error(`Sentry request failed (${response.status}): ${responseBody}`);
    }

    return response;
}

async function loadSentryIssues(baseUrl, organization, query, token) {
    const issues = [];
    const parameters = new URLSearchParams({
        limit: '100',
        query,
        sort: 'new',
    });
    let nextUrl = `${baseUrl}/api/0/organizations/${encodeURIComponent(organization)}/issues/?${parameters}`;

    while (nextUrl) {
        const response = await sentryRequest(nextUrl, token);
        const page = await response.json();
        issues.push(...page);
        nextUrl = findNextPage(response);
    }

    return issues;
}

async function loadRecommendedEvent(baseUrl, organization, issueId, token) {
    const url = `${baseUrl}/api/0/organizations/${encodeURIComponent(organization)}/issues/${issueId}/events/recommended/`;
    const response = await sentryRequest(url, token);

    return response.json();
}

async function loadExistingCards() {
    const directoryEntries = await readdir(WORKING_FOLDER, { withFileTypes: true });
    const markdownFileNames = directoryEntries
        .filter((entry) => entry.isFile() && entry.name.endsWith('.md'))
        .map((entry) => entry.name);

    const cards = await Promise.all(markdownFileNames.map(async (fileName) => {
        const content = await readFile(path.join(WORKING_FOLDER, fileName), 'utf8');

        return { content, fileName };
    }));

    return cards;
}

function collectImportedSentryIssueIds(cards) {
    return new Set(cards
        .map(({ content }) => content.match(SENTRY_ISSUE_ID_PATTERN)?.[1])
        .filter((issueId) => !!issueId));
}

function findNextBugNumber(cards) {
    const numbers = cards
        .map(({ fileName }) => fileName.match(BUG_FILE_PATTERN)?.[1])
        .filter((number) => !!number)
        .map((number) => Number.parseInt(number, 10));

    return numbers.length > 0 ? Math.max(...numbers) + 1 : 1;
}

function findException(event) {
    const exceptionEntry = event.entries?.find((entry) => entry.type === 'exception');

    return exceptionEntry?.data?.values?.at(-1) ?? null;
}

function formatStackTrace(event) {
    const exception = findException(event);
    const frames = exception?.stacktrace?.frames ?? [];

    if (frames.length === 0) return 'No stack trace was supplied by Sentry.';

    return frames
        .slice(-30)
        .map((frame) => {
            const location = [frame.filename, frame.lineNo, frame.colNo]
                .filter((value) => value !== undefined && value !== null)
                .join(':');

            return `at ${frame.function ?? '<anonymous>'} (${location})`;
        })
        .join('\n')
        .replace(/```/gu, '`\u200b``');
}

function buildCardContent(issue, event, bugNumber) {
    const id = `B_${bugNumber}`;
    const title = issue.title.replace(/\s+/gu, ' ').trim();
    const exception = findException(event);
    const errorMessage = exception?.value ?? event.message ?? issue.title;

    return `---
id: ${id}
internalId: ${randomUUID()}
title: ${quoteYaml(title)}
status: to fix
sentryIssueId: ${quoteYaml(issue.id)}
sentryShortId: ${quoteYaml(issue.shortId)}
sentryUrl: ${quoteYaml(issue.permalink)}
---

${errorMessage}

## Sentry context

- First seen: ${issue.firstSeen}
- Last seen: ${issue.lastSeen}
- Occurrences: ${issue.count}
- Culprit: ${issue.culprit ?? 'Unknown'}
- Event: ${event.eventID}

## Stack trace

\`\`\`text
${formatStackTrace(event)}
\`\`\`
`;
}

async function importIssues() {
    const token = requireEnvironmentVariable('SENTRY_AUTH_TOKEN');
    const organization = requireEnvironmentVariable('SENTRY_ORGANIZATION');
    const baseUrl = process.env.SENTRY_BASE_URL?.trim() || 'https://sentry.io';
    const query = process.env.SENTRY_QUERY?.trim() || 'is:unresolved environment:production';

    const cards = await loadExistingCards();
    const importedIssueIds = collectImportedSentryIssueIds(cards);
    const issues = await loadSentryIssues(baseUrl, organization, query, token);
    const missingIssues = issues.filter((issue) => !importedIssueIds.has(issue.id));

    let nextBugNumber = findNextBugNumber(cards);

    for (const issue of missingIssues) {
        const event = await loadRecommendedEvent(baseUrl, organization, issue.id, token);
        const content = buildCardContent(issue, event, nextBugNumber);
        const fileName = `B_${nextBugNumber}_${slugify(issue.title)}.md`;

        await writeFile(path.join(WORKING_FOLDER, fileName), content, { flag: 'wx' });
        nextBugNumber += 1;
    }

    console.log(`Imported ${missingIssues.length} Sentry issues.`);
}

await importIssues();
```

It uses Sentry’s organization issues endpoint and retrieves the recommended event for the full error context. Both require an API token with `event:read`. [Issues API](https://docs.sentry.io/api/events/list-an-organizations-issues/), [event API](https://docs.sentry.io/api/events/retrieve-an-issue-event/).

## Without merging

Yes. Push the generated files directly to `main`.

```yaml
name: Import Sentry bugs

on:
  schedule:
    - cron: '17 * * * *'
  workflow_dispatch:

permissions:
  contents: write

concurrency:
  group: sentry-bug-import
  cancel-in-progress: false

jobs:
  import:
    runs-on: windows-latest

    steps:
      - uses: actions/checkout@v4
        with:
          fetch-depth: 0

      - uses: actions/setup-node@v4
        with:
          node-version: 22

      - name: Import Sentry issues
        shell: powershell
        env:
          SENTRY_AUTH_TOKEN: ${{ secrets.SENTRY_AUTH_TOKEN }}
          SENTRY_ORGANIZATION: your-sentry-organization
          SENTRY_QUERY: 'is:unresolved environment:production'
        run: node scripts/import_sentry_issues.mjs

      - name: Commit imported bugs
        shell: powershell
        run: |
          git diff --quiet -- design/feature_descriptions
          if ($LASTEXITCODE -eq 0) {
              Write-Host "No new bugs."
              exit 0
          }

          git config user.name "Sentry bug importer"
          git config user.email "sentry-importer@users.noreply.github.com"
          git add design/feature_descriptions
          git commit -m "Import Sentry bug reports"
          git push origin HEAD:main
```

The `concurrency` setting prevents two importer runs from choosing the same next `B_` number. `writeFile(..., { flag: 'wx' })` is a second safeguard against overwriting an existing card.

Direct push will only work if branch protection permits GitHub Actions to write to `main`. If it does not, the options are a PR or an explicitly authorized branch-protection bypass.

